// Space: O(1)

class Solution {
public:
    long long getDescentPeriods(vector<int>& prices) {
        int64_t result = 0;
        for (int64_t i = 0, l = 0; i < size(prices); ++i) {
            ++l;
            if (i + 1 == size(prices) || prices[i] - 1 != prices[i + 1]) {
                result += l * (l + 1) / 2;
                l = 0;
            }
        }
        return result;
    }
};

kamyu-c-number-of-spaces-cleaning-robot-:
// Time:  O(m * n)
// Space: O(1)

class Solution {
public:
    int numberOfCleanRooms(vector<vector<int>>& room) {
        static const vector<pair<int, int>> directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int result = 0, r = 0, c = 0, d = 0;
        while (!(room[r][c] & (1 << (d + 1)))) {
            result += (room[r][c] >> 1) == 0;
            room[r][c] |= (1 << (d + 1));
            const auto& [dr, dc] = directions[d];
            const int nr = r + dr, nc = c + dc;
            if ((0 <= nr && nr < size(room)) && (0 <= nc && nc < size(room[0])) && !(room[nr][nc] & 1)) {
                r = nr, c = nc;
            } else {
                d = (d + 1) % 4;
            }
        }
        return result;
    }
};

kamyu-c-number-of-squareful-arrays-1dgmv:
// Time:  O(n!)
// Space: O(n^2)

class Solution {
public:
    int numSquarefulPerms(vector<int>& A) {
        unordered_map<int, int> count;
        for (const auto& a : A) {
            ++count[a];
        }
        unordered_map<int, unordered_set<int>> candidate;
        for (const auto& i : count) {
            for (const auto& j : count) {
                int x = i.first, y = j.first, s = sqrt(x + y);
                if (s * s == x + y) {
                    candidate[x].emplace(y);
                }
            }
        }

        int result = 0;
        for (const auto& i : count) {
            dfs(candidate, i.first, A.size() - 1, &count, &result);
        }
        return result;
    }

private:
    void dfs(const unordered_map<int, unordered_set<int>>& candidate,
             int x,
             int left,
             unordered_map<int, int> *count,
             int *result) {

        --(*count)[x];
        if (!left) {
            ++(*result);
        }
        if (candidate.count(x)) {
            for (const auto& y : candidate.at(x)) {
                if ((*count)[y] > 0) {
                    dfs(candidate, y, left - 1, count, result);
                }
            }
        }
        ++(*count)[x];
    }
};

kamyu-c-number-of-stable-subsequences-01:
// Time:  O(n)
// Space: O(1)

// dp
class Solution {
public:
    int countStableSubsequences(vector<int>& nums) {
        static const int MOD = 1e9 + 7;

        vector<vector<int64_t>> dp(2, vector<int64_t>(2));  // dp[p][i]: count of subsequences that end with exactly (i+1) consecutive numbers of parity p
        for (const auto& x : nums) {
            const auto& p = x % 2;
            dp[p][1] = (dp[p][1] + dp[p][0]) % MOD;
            dp[p][0] = (dp[p][0] + 1 + dp[1 ^ p][0] + dp[1 ^ p][1]) % MOD;
        }
        return (dp[0][0] + dp[0][1] + dp[1][0] + dp[1][1]) % MOD;
    }
};

kamyu-c-number-of-steps-to-reduce-a-numb:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int numSteps(string s) {
        int result = 0, carry = 0;
        for (int i = s.length() - 1; i > 0; --i) {
            if (s[i] - '0' + carry == 1) {
                carry = 1;  // once it was set, it would keep carrying forever
                result += 2;
            } else {
                ++result;
            }
        }
        return result + carry;
    }
};

// Time:  O(logn)
// Space: O(1)

class Solution {
public:
    int numberOfSteps (int num) {
        int result = 0;
        while (num) {
            result += (num & 1) ? 2 : 1;
            num >>= 1;
        }
        return max(result - 1, 0);
    }
};

kamyu-c-number-of-strings-that-appear-as:
// Time:  O(n * l + m), n is the number of patterns
//                    , l is the max length of patterns
//                    , m is the length of word     
// Space: O(t)        , t is the total size of ac automata trie

struct AhoNode {
    vector<unique_ptr<AhoNode>> children;
    vector<int> indices;
    AhoNode *suffix;
    AhoNode *output;
    AhoNode()
      : children(26)
      , suffix(nullptr)
      , output(nullptr) {}
};

class AhoTrie {
public:
    AhoTrie(const vector<string>& patterns) : root_(createACTrie(patterns)) {
        node_ = createACSuffixAndOutputLinks(root_.get());
    }

    vector<int> step(char letter) {
        while (node_ && !node_->children[letter - 'a']) {
            node_ = node_->suffix;
        }
        node_ = node_ ? node_->children[letter - 'a'].get() : root_.get();
        return getACNodeOutputs(node_);
    }

    void reset() {
        node_ = root_.get();
    }

private:
    unique_ptr<AhoNode> createACTrie(const vector<string>& patterns) {  // Time:  O(n * l), Space: O(t)
        auto root = make_unique<AhoNode>();
        for (int i = 0; i < patterns.size(); ++i) {
            auto node = root.get();
            for (const auto& c : patterns[i]) {
                if (!node->children[c - 'a']) {
                    node->children[c - 'a'] = make_unique<AhoNode>();
                }
                node = node->children[c - 'a'].get();
            }
            node->indices.emplace_back(i);
        }
        return root;
    }

    AhoNode *createACSuffixAndOutputLinks(AhoNode *root) {  // Time: O(n * l), Space: O(t)
        queue<AhoNode *> q;
        for (int c = 0; c < size(root->children); ++c) {
            auto node = root->children[c].get();
            if (!node) {
                continue;
            }
            q.emplace(node);
            node->suffix = root;
        }

        while (!q.empty()) {
            auto node = q.front(); q.pop();
            for (int c = 0; c < size(node->children); ++c) {
                if (!node->children[c]) {
                    continue;
                }
                auto child = node->children[c].get();
                q.emplace(child);
                auto suffix = node->suffix;
                while (suffix && !suffix->children[c]) {
                    suffix = suffix->suffix;
                }
                child->suffix = suffix ? suffix->children[c].get() : root;
                child->output = !child->suffix->indices.empty() ?
                    child->suffix : child->suffix->output;
            }
        }

        return root;
    }

    vector<int> getACNodeOutputs(AhoNode *node) {  // Total Time: O(n), modified
        vector<int> result;
        if (!lookup_.count(node)) {  // modified
            lookup_.emplace(node);  // modified
            for (const auto& i : node_->indices) {
                result.emplace_back(i);
            }
            auto output = node_->output;
            while (output && !lookup_.count(output)) {  // modified
                lookup_.emplace(output);
                for (const auto& i : output->indices) {  // modified
                    result.emplace_back(i);
                }
                output = output->output;
            }
        }
        return result;
    }

    unique_ptr<AhoNode> root_;
    AhoNode *node_;
    unordered_set<AhoNode *> lookup_;  // modified
};

// ac automata solution
class Solution {
public:
    int numOfStrings(vector<string>& patterns, string word) {
        auto trie = AhoTrie(patterns);
        return accumulate(cbegin(word), cend(word), 0,
                          [&trie](int total, const auto& x) {
                              return total + size(trie.step(x));
                          });
    }
};

// Time:  O(n * (l + m)), n is the number of patterns
//                      , l is the max length of patterns
//                      , m is the length of word
// Space: O(l)
// kmp solution
class Solution2 {
public:
    int numOfStrings(vector<string>& patterns, string word) {
        return accumulate(cbegin(patterns), cend(patterns), 0,
                          [this, &word](int total, const auto& x) {
                              return total + static_cast<int>(kmp(word, x) != -1);
                          });
    }

private:
    int kmp(const string& text, const string& pattern) {
        if (pattern.empty()) {
            return 0;
        }
        const auto& prefix = getPrefix(pattern);
        if (text.length() < pattern.length()) {
            return -1;
        }
        int j = -1;
        for (int i = 0; i < text.length(); ++i) {
            while (j != -1 && pattern[j + 1] != text[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == text[i]) {
                ++j;
            }
            if (j + 1 == pattern.length()) {
                return i - j;
            }
        }
        return -1;
    }

    vector<int> getPrefix(const string& pattern) {
        vector<int> prefix(pattern.length(), -1);
        int j = -1;
        for (int i = 1; i < pattern.length(); ++i) {
            while (j != -1 && pattern[j + 1] != pattern[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == pattern[i]) {
                ++j;
            }
            prefix[i] = j;
        }
        return prefix;
    }
};

// Time:  O(n * m * l), n is the number of patterns
