        static const int MOD = 1e9 + 7;

        vector<int> dp(2);
        for (const auto& x : nums) {
            vector<int> new_dp(2);
            for (int i = 0; i < 2; ++i) {
                new_dp[i] = (dp[i] + dp[i ^ (x % 2)] + (x % 2 == i ? 1 : 0)) % MOD;
            }
            dp = move(new_dp);
        }
        return dp[1];
    }
};

