        for (int i = 0; i <= size(sentence); ++i) {
            if (i == size(sentence) || sentence[i] == ' ') {
                if (token == 1) {
                    ++result;
                }
                token = hyphen = 0;
                continue;
            }
            if (isdigit(sentence[i]) ||
                (string("!.,").find(sentence[i]) != string::npos && !(i == size(sentence) - 1 || sentence[i + 1] == ' ')) ||
