        vector<vector<int>> adj(size(edges) + 1);
        for (const auto& e : edges) {
            adj[e[0] - 1].emplace_back(e[1] - 1);
            adj[e[1] - 1].emplace_back(e[0] - 1);
        }
        const auto& bfs = [&]() {
            int d = -1;
            vector<bool> lookup(size(adj));
            lookup[0] = true;
