// Time:  O(n^2)
// Space: O(n)

// dp
class Solution {
public:
    int houseOfCards(int n) {
        vector<int> dp(n + 1);  // dp[i]: number of ways with i cards and at most t triangles in the first row
        dp[0] = 1;
        for (int t = 1; t <= (n + 1) / 3; ++t) {
            for (int i = n; i >= 3 * t - 1; --i) {
                dp[i] += dp[i - (3 * t - 1)];
            }
        }
        return dp[n];
    }
};

// Time:  O(n^3)
// Space: O(n^2)
// dp
class Solution_TLE {
public:
    int houseOfCards(int n) {
        vector<vector<int>> dp((n + 1) / 3 + 1, vector<int>(n + 1));  // dp[t][i]: number of ways with i cards and t triangles in the lowest row
        dp[0][0] = 1;
        for (int t = 1; t <= (n + 1) / 3; ++t) {
            for (int i = 3 * t - 1; i <= n; ++i) {
                for (int j = 0; j < t; ++j) {
                    dp[t][i] += dp[j][i - (3 * t - 1)];
                }
            }
        }
        return accumulate(cbegin(dp), cend(dp), 0,
                          [](const auto& total, const auto& x) {
                              return total + x.back();
                          });
    }
};

kamyu-c-number-of-ways-to-build-sturdy-b:
// Time:  O(h * p^2), p is the number of patterns
// Space: O(p^2)

// bitmask, backtracking, dp
class Solution {
public:
    int buildWall(int height, int width, vector<int>& bricks) {
        static const int MOD = 1e9 + 7;
        vector<int> patterns;
        unordered_set<int> lookup;
        backtracking(height, width, bricks, 0, 0, &lookup, &patterns);
        vector<vector<int>> adj(size(patterns));
        for (int i = 0; i < size(patterns); ++i) {
            for (int j = 0; j < size(patterns); ++j) {
                if (!(patterns[i] & patterns[j])) {
                    adj[i].emplace_back(j);
                }
            }
        }
        vector<vector<int>> dp = {vector<int>(size(patterns), 1), vector<int>(size(patterns), 0)};
        for (int i = 0; i < height; ++i) {
            for (int j = 0; j < size(patterns); ++j) {
                dp[(i + 1) % 2][j] = 0;
                for (const auto& k : adj[j]) {
                    dp[(i + 1) % 2][j] = (dp[(i + 1) % 2][j] + dp[i % 2][k]) % MOD;
                }
            }
        }
        return accumulate(cbegin(dp[(height - 1) % 2]), cend(dp[(height - 1) % 2]), 0,
                          [](const auto& total, const auto& x) {
                              return (total + x) % MOD;
                          });  // Time: O(p)
    }

private:
    void backtracking(
        int height, int width, const vector<int>& bricks,
        int total, int mask,
        unordered_set<int> *lookup,
        vector<int> *patterns) {

        if (lookup->count(mask)) {
            return;
        }
        lookup->emplace(mask);
        if (total >= width) {
            if (total == width) {
                patterns->emplace_back(mask ^ (1 << width));
            }
            return;
        }
        for (const auto& x : bricks) {
            backtracking(height, width, bricks, total + x, mask | (1 << (total + x)), lookup, patterns);
        }
    }
};

// Time:  O(p^3 * logh), p is the number of patterns, p may be up to 512
// Space: O(p^3)
// bitmask, backtracking, matrix exponentiation
class Solution_TLE {
public:
    int buildWall(int height, int width, vector<int>& bricks) {
        vector<int> patterns;
        unordered_set<int> lookup;
        backtracking(height, width, bricks, 0, 0, &lookup, &patterns);
        if (empty(patterns)) {
            return 0;
        }
        vector<vector<int>> matrix;
        vector<vector<int>> counts = {vector<int>(size(patterns), 1)};
        for (const auto& mask1 : patterns) {
            matrix.emplace_back();
            for (const auto& mask2 : patterns) {
                matrix.back().emplace_back(static_cast<int>((mask1 & mask2) == 0));
            }
        }
        const auto& result = matrixMult(counts, matrixExpo(matrix, height - 1));  // Time: O(p^3 * logh), Space: O(p^2)
        return accumulate(cbegin(result[0]), cend(result[0]), 0,
                          [](const auto& total, const auto& x) {
                              return (total + x) % MOD;
                          });  // Time: O(p)
    }

private:
    void backtracking(
        int height, int width, const vector<int>& bricks,
        int total, int mask,
        unordered_set<int> *lookup,
        vector<int> *patterns) {

        if (lookup->count(mask)) {
            return;
        }
        lookup->emplace(mask);
        if (total >= width) {
            if (total == width) {
                patterns->emplace_back(mask ^ (1 << width));
            }
            return;
        }
        for (const auto& x : bricks) {
            backtracking(height, width, bricks, total + x, mask | (1 << (total + x)), lookup, patterns);
        }

    }

    vector<vector<int>> matrixExpo(const vector<vector<int>>& A, int pow) {
        vector<vector<int>> result(A.size(), vector<int>(A.size()));
        vector<vector<int>> A_exp(A);
        for (int i = 0; i < A.size(); ++i) {
            result[i][i] = 1;
        }
        while (pow) {
            if (pow % 2 == 1) {
                result = matrixMult(result, A_exp);
            }
            A_exp = matrixMult(A_exp, A_exp);
            pow /= 2;
        }
        return result;
    }

    vector<vector<int>> matrixMult(const vector<vector<int>>& A, const vector<vector<int>>& B) {
        vector<vector<int>> result(A.size(), vector<int>(B[0].size()));
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < B[0].size(); ++j) {
                int64_t entry = 0;
                for (int k = 0; k < B.size(); ++k) {
                    entry = (static_cast<int64_t>(A[i][k]) * B[k][j] % MOD + entry) % MOD;
                }
                result[i][j] = static_cast<int>(entry);
            }
        }
        return result;
    }

    static const int MOD = 1e9 + 7;
};

kamyu-c-number-of-ways-to-buy-pens-and-p:
// Time:  O(min(t / c1, c2 / g)) = O(sqrt(t)), c1 = max(cost1, cost2)
//                                           , c2 = min(cost1, cost2)
//                                           ,  g = gcd(c1, c2)
// Space: O(1)

// math
class Solution {
public:
    long long waysToBuyPensPencils(int total, int cost1, int cost2) {
        const auto& ceil_divide = [](const auto& a, const auto& b) {
            return (a + b - 1) / b;
        };
        const auto& arithmetic_progression_sum  = [](const auto& a, const auto& d, const auto& l) {
            return (a + (a + (l - 1) * d)) * l / 2;
        };
        if (cost1 < cost2) {
            swap(cost1, cost2);
        }
        const auto& lcm = static_cast<int64_t>(cost1) / gcd(cost1, cost2) * cost2;
        const auto& d = lcm / cost2;
        int64_t result = 0;
        for (int i = 0; i <= min(total / cost1, static_cast<int>(lcm / cost1) - 1); ++i) {
            // total, cost1, cost2 = 120, 7, 5
            // => cnt decreases by a fixed value every lcm(cost1, cost2) 
            // => arithmetic progressions of cnts are as follows
            //      ----- l -----  x
            //  |   24, 17, 10, 3 120
            //  |   22, 15,  8, 1 113
            // cnt  21, 14,  7,   106
            //  |   19, 12,  5,    99
            //  |   18, 11,  4,    92
            const auto& cnt = (total - i * cost1) / cost2 + 1;
            const auto& l = ceil_divide(cnt, d);
            result += arithmetic_progression_sum(cnt, -d, l);
        }
        return result;
    }
};

// Time:  O(t / c1), c1 = max(cost1, cost2)
//                 , c2 = min(cost1, cost2)
// Space: O(1)
