        if (cost1 < cost2) {
            swap(cost1, cost2);
        }
        int64_t result = 0;
        for (int i = 0; i <= total / cost1; ++i) {
            result += (total - i * cost1) / cost2 + 1;
        }
        return result;
    }
};

