        uint64_t aba = 6, abc = 6;
        for (int i = 1; i < n; ++i) {
            tie(aba, abc) = pair((3 * aba % MOD + 2 * abc % MOD) % MOD,
                                 (2 * abc % MOD + 2 * aba % MOD) %MOD);
        }
        return (aba + abc) % MOD;
    }
};

