                                 {1, m - 2,     0,             n - 1},
                                 {1,   0,   n - 2,             m - 1},
                                 {0,   1,       1, (n - 2) + (m - 2)}};
        dp = matrixMult({dp}, matrixExpo(T, k))[0];
        return dp[0];
    }

private:
    vector<vector<int>> matrixExpo(const vector<vector<int>>& A, int64_t pow) {
        vector<vector<int>> result(A.size(), vector<int>(A.size()));
        vector<vector<int>> A_exp(A);
        for (int i = 0; i < A.size(); ++i) {
            result[i][i] = 1;
        }
