// Space: O(2^n)

class Solution {
public:
    int numberWays(vector<vector<int>>& hats) {
        static const int MOD = 1e9 + 7;
        static const int HAT_SIZE = 40;

        vector<vector<int>> hat_to_people(HAT_SIZE);
        for (int i = 0; i < hats.size(); ++i) {
            for (const auto& hat: hats[i]) {
                hat_to_people[hat - 1].emplace_back(i);
            }
        }
        vector<int> dp(1 << hats.size());
        dp[0] = 1;    
        for (const auto& people : hat_to_people) {
            for (int mask = dp.size() - 1; mask >= 0; --mask) {
                for (const int& p: people) {
                    if (mask & (1 << p)) {
                        continue;
                    }
                    dp[mask | (1 << p)] += dp[mask];
                    dp[mask | (1 << p)] %= MOD;
                }
            }
        }
        return dp.back();
    }
};

kamyu-c-number-of-ways-where-square-of-n:
// Time:  O(m * n)
// Space: O(m + n)

class Solution {
public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
        int result = 0;
        for (const auto& n : nums1) {
            result += twoProduct(nums2, static_cast<int64_t>(n) * n);
        }
        for (const auto& n : nums2) {
            result += twoProduct(nums1, static_cast<int64_t>(n) * n);
        }
        return result;
    }

private:
    int twoProduct(const vector<int>& nums, int64_t i) {
        unordered_map<int, int> lookup;
        int count = 0;
        for (const auto& num : nums) {
            if (i % num) {
                continue;
            }
            count += lookup[i / num];
            ++lookup[num];
        }
        return count;
    }  
};

kamyu-c-number-of-wonderful-substrings-0:
// Time:  O(n)
// Space: O(2^10)

class Solution {
public:
    long long wonderfulSubstrings(string word) {
        static const int ALPHABET_SIZE = 10;
        vector<int> count(pow(2, ALPHABET_SIZE));
        count[0] = 1;
        long long result = 0;
        int curr = 0;
        for (const auto& c : word) {
            curr ^= 1 << (c - 'a');
            result += count[curr];
            for (int i = 0; i < ALPHABET_SIZE; ++i) {
                result += count[curr ^ (1 << i)];
            }
            ++count[curr];
        }
        return result;
    }
};

