// Space: O(1)

// two pointers, combinatorics
class Solution {
public:
    long long zeroFilledSubarray(vector<int>& nums) {
        int64_t result = 0;
        for (int i = 0, prev = -1; i < size(nums); ++i) {
            if (nums[i]) {
                prev = i;
                continue;
            }
            result += i - prev;
        }
        return result;
    }
};

kamyu-c-number-of-zigzag-arrays-i-0w79wd:
// Time:  O(n * (r - l))
// Space: O(r - l)

// prefix sum, dp
class Solution {
public:
    int zigZagArrays(int n, int l, int r) {
        static const int MOD = 1e9 + 7;

        r -= l;
        vector<int> dp(r + 1, 1);
        for (int _ = 0; _ < n - 1; ++_) {
            for (int i = 0, prefix = 0; i < size(dp); ++i) {
                tie(dp[i], prefix) = pair(prefix, (prefix + dp[i]) % MOD);
            }
            reverse(begin(dp), end(dp));
        }
        int result = 0;
        for (const auto& x : dp) {
            result = (result + x) % MOD;
        }
        return (result * 2) % MOD;
    }
};

kamyu-c-number-of-zigzag-arrays-ii-1peif:
// Time:  O((r - l)^3 * logn)
// Space: O((r - l)^2)

// matrix fast exponentiation
class Solution {
public:
    int zigZagArrays(int n, int l, int r) {
        r -= l;
        vector<vector<int>> matrix(r + 1, vector<int>(r + 1));
        for (int i = 0; i <= r; ++i) {
            for (int j = 0; j <= r - 1 - i; ++j) {
                matrix[i][j] = 1;
            }
        }
        const auto& matrix_pow_t = matrixExpo(matrix, n - 1);
        const auto& result = matrixMult(vector<vector<int>>{vector<int>(r + 1, 1)}, matrix_pow_t);
        return (accumulate(cbegin(result[0]), cend(result[0]), 0, [](const auto& accu, const auto& x) {
            return (accu + x) % MOD;
        }) * 2) % MOD;
    }

private:
    vector<vector<int>> matrixExpo(const vector<vector<int>>& A, int64_t pow) {
        vector<vector<int>> result(size(A), vector<int>(size(A)));
        vector<vector<int>> A_exp(A);
        for (int i = 0; i < size(A); ++i) {
            result[i][i] = 1;
        }
        while (pow) {
            if ((pow & 1) == 1) {
                result = matrixMult(result, A_exp);
            }
            A_exp = matrixMult(A_exp, A_exp);
            pow >>= 1;
        }
        return result;
    }

    vector<vector<int>> matrixMult(const vector<vector<int>>& A, const vector<vector<int>>& B) {
        vector<vector<int>> result(size(A), vector<int>(size(B[0])));
        for (int i = 0; i < size(A); ++i) {
            for (int j = 0; j < size(B[0]); ++j) {
                int64_t entry = 0;
                for (int k = 0; k < size(B); ++k) {
                    entry = (static_cast<int64_t>(A[i][k]) * B[k][j] % MOD + entry) % MOD;
                }
                result[i][j] = static_cast<int>(entry);
            }
        }
        return result;
    }

    static const int MOD = 1e9 + 7;
};

kamyu-c-number-of-zigzag-arrays-iii-1nep:
// Time:  O(n^3)
// Space: O(n)

// dp, prefix sum, lagrange interpolation
class Solution {
public:
    int zigZagArrays(int n, int l, int r) {
        static const uint32_t MOD = 1e9 + 7;

        vector<int64_t> inv = {1, 1};
        vector<int64_t> inv_fact = {1, 1};
        const auto& inv_factorial = [&](int n) {
            while (size(inv) <= n) {  // lazy initialization
                inv.emplace_back((static_cast<int64_t>(inv[MOD % size(inv)]) * (MOD - MOD / size(inv))) % MOD);  // https://cp-algorithms.com/algebra/module-inverse.html
                inv_fact.emplace_back((static_cast<int64_t>(inv_fact.back()) * inv.back()) % MOD);
            }
            return inv_fact[n];
        };

        const auto& f = [&](int x) {
            vector<int64_t> dp(x);
            iota(begin(dp), end(dp), 0);
            for (int _ = 0; _ < n - 2; ++_) {
                vector<int64_t> new_dp(x);
                for (int i = 0; i + 1 < x; ++i) {
                    new_dp[i + 1] = (new_dp[i] + dp[x - 1 - i]) % MOD;
                }
                dp = move(new_dp);
            }
            int64_t total = 0;
            for (int i = 0; i < x; ++i) {
                total = (total + dp[i]) % MOD;
            }
            return (total * 2) % MOD;
        };

        const auto& m = r - l + 1;
        if (m <= n + 1) {
            return f(m);
        }
        vector<int64_t> prefix((n + 1) + 1);
        prefix[0] = 1;
        for (int i = 0; i + 1 < size(prefix); ++i) {
            prefix[i + 1] = prefix[i] * (((m - 1 - i) % MOD + MOD) % MOD) % MOD;
        }
        vector<int64_t> suffix((n + 1) + 1);
        suffix.back() = 1;
        for (int i = size(suffix) - 2; i >= 0; --i) {
            suffix[i] = suffix[i + 1] * (((m - 1 - i) % MOD + MOD) % MOD) % MOD;
        }
        int result = 0;
        for (int i = 0; i < n + 1; ++i) {
            result = (result + (((((f(i + 1) * ((prefix[i] * suffix[i + 1]) % MOD)) % MOD) * ((inv_factorial(i) * inv_factorial(n - i)) % MOD)) % MOD) * ((n - i) % 2 ? (MOD - 1) : 1)) % MOD) % MOD;
        }
        return result;
    }
};

kamyu-c-numbers-at-most-n-given-digit-se:
// Time:  O(logn)
// Space: O(logn)

class Solution {
public:
    int atMostNGivenDigitSet(vector<string>& D, int N) {
        string str_N = to_string(N);
        unordered_set<string> set_D(D.cbegin(), D.cend());
        int result = 0;
        for (int i = 1 ; i < str_N.length() ; ++i) {
            result += pow(D.size(), i);  // x, xx, xxx
        }
        int i = 0;
        // assume N = 1234, D = 1, 2, 3, 4
        for (i = 0 ; i < str_N.length() ; ++i) {
            for (const auto& d : D) {
                if (d[0] < str_N[i]) {
                    // 11xx; 121x, 122x; 1231, 1232, 1233;
                    result += pow(D.size(), str_N.length() - i - 1);
                } else {
                    break;
                }
            }
            if (!set_D.count(string(1, str_N[i]))) {
                break;
            }
        }               
        return result + int(i == str_N.length());  // 1234
    }
};

kamyu-c-numbers-with-repeated-digits-05v:
// Time:  O(logn)
// Space: O(logn)

class Solution {
public:
    int numDupDigitsAtMostN(int N) {
        const auto& digits = to_string(N + 1);
        int result = 0;

        // Given 321
        //
        // 1. count numbers without repeated digits:
        // - X
        // - XX
        for (int i = 1; i < digits.length(); ++i) {
            result += P(9, 1) * P(9, i - 1);
        }

        // 2. count numbers without repeated digits:
        // - 1XX ~ 3XX
        // - 30X ~ 32X
        // - 320 ~ 321
        unordered_set<int> prefix_set;
        for (int i = 0; i < digits.length(); ++i) {
            for (int d = (i == 0) ? 1 : 0; d < digits[i] - '0'; ++d) {
                if (prefix_set.count(d)) {
                    continue;
                }
                result += P(9 - i, digits.length() - i - 1);
            }
            if (prefix_set.count(digits[i] - '0')) {
                break;
            }
            prefix_set.emplace(digits[i] - '0');
        }
        return N - result;
    }

private:
    int P(int m, int n) const {
        int result = 1;
        while (n--) {
            result *= m--;
        }
        return result;
    }
};

kamyu-c-numbers-with-same-consecutive-di:
// Time:  O(2^n)
// Space: O(2^n)

class Solution {
public:
    vector<int> numsSameConsecDiff(int N, int K) {
        vector<int> curr(10);
        iota(curr.begin(), curr.end(), 0);
        for (int i = 0; i < N - 1; ++i) {
            vector<int> next;
            for (const auto& x : curr) {
                int y = x % 10;
                if (x > 0 && y + K < 10) {
                    next.emplace_back(x * 10 + y + K);
                }
                if (x > 0 && K > 0 && y - K >= 0) {
                    next.emplace_back(x * 10 + y - K);
                }
            }
            curr = move(next);
        }
        return curr;
    }
};

kamyu-c-numdistinct-1hzp9o0:
// Time Complexity: O(m * n)
// Space Complexity: O(n)

class Solution {
    public:
        int numDistinct(const string &S, const string &T) {
            vector<int> f(T.size() + 1);
            f[0] = 1; // f(0, 0) = 1, means S = "" and T = "", there is only one distinct subsequence, i.e. ""
            for (int i = 1; i <= S.size(); ++i) {
                for (int j = T.size(); j > 0; --j) {
                    // f(i, j) is composed of:
                    // f(i−1,j): not using S[i - 1] 
                    // f(i−1,j−1): using S[i - 1] if S[i - 1] == S[j - 1]
                    f[j] += (S[i - 1] == T[j - 1]) ? f[j - 1] : 0;
                }
            }
            return f[T.size()];
        }
};

kamyu-c-occurrences-after-bigram-13nb2sc:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<string> findOcurrences(string text, string first, string second) {
        vector<string> result;
        first.push_back(' ');
        second.push_back(' ');
        string third;
        int i = 0, j = 0, k = 0;
        while (k < text.length()) {
            auto c = text[k++];
            if (i != first.length()) {
                if (c == first[i]) {
                    ++i;
                } else {
                    i = 0;
                }
                continue;
            }
            if (j != second.length()) {
                if (c == second[j]) {
                    ++j;
                } else {
                    k -= j + 1;
                    i = 0, j = 0;
                }
                continue;
            }
            if (c != ' ') {
                third.push_back(c);
                continue;
            }
            k -= second.length() + third.length() + 1;
            i = 0, j = 0;
            result.emplace_back(move(third));
        }
        if (!third.empty()) {
            result.emplace_back(move(third));
        }
        return result;
    }
};

kamyu-c-odd-even-jump-1d4l1xj:
// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int oddEvenJumps(vector<int>& A) {
        vector<int> idx(A.size());
        iota(idx.begin(), idx.end(), 0);

        sort(idx.begin(), idx.end(),
             [&](int a, int b) {
                 return A[a] != A[b] ? A[a] < A[b] : a < b;
             });
        const auto& next_higher = findNext(idx);
        sort(idx.begin(), idx.end(),
             [&](int a, int b) {
                 return A[a] != A[b] ? A[a] > A[b] : a < b;
             });
        const auto& next_lower = findNext(idx);

        vector<bool> odd(A.size()), even(A.size());
        odd.back() = even.back() = true;
        for (int i = A.size() - 2; i >= 0; --i) {
            if (next_higher[i] != -1) {
                odd[i] = even[next_higher[i]];
            }
            if (next_lower[i] != -1) {
                even[i] = odd[next_lower[i]];
            }
        }
        return count(odd.cbegin(), odd.cend(), true);
    }

private:
    vector<int> findNext(const vector<int>& idx) {
        vector<int> result(idx.size(), -1);
        vector<int> stack;
        for (const auto& i : idx) {
            while (!stack.empty() && stack.back() < i) {
                result[stack.back()] = i, stack.pop_back();
            }
            stack.emplace_back(i);
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(n)
class Solution2 {
public:
    int oddEvenJumps(vector<int>& A) {
        vector<bool> odd(A.size()), even(A.size());
        odd.back() = even.back() = true;
        map<int, int> reachables{{A.back(), A.size() - 1}};
        for (int i = A.size() - 2; i >= 0; --i) {
            auto high = reachables.lower_bound(A[i]);
            if (high != reachables.cend()) {
                odd[i] = even[high->second];
            }
            auto low = reachables.upper_bound(A[i]);
            if (low != reachables.cbegin()) {
                even[i] = odd[prev(low)->second];
            }
            reachables[A[i]] = i;
        }
        return count(odd.cbegin(), odd.cend(), true); 
    }
};

