// Time:  O(m * n), m is the number of words, n is the length of each word
// Space: O(1)

// freq table
class Solution {
public:
    string oddString(vector<string>& words) {
        for (int i = 0; i < size(words[0]) - 1; ++i) {
            unordered_map<int, vector<int>> lookup;
            for (int j = 0; j < size(words); ++j) {
                if (size(lookup[words[j][i + 1] - words[j][i]]) < 2) {
                    lookup[words[j][i + 1] - words[j][i]].emplace_back(j);
                }
            }
            if (size(lookup) == 2) {
                return size(cbegin(lookup)->second) == 1
                       ? words[cbegin(lookup)->second[0]]
                       : words[next(cbegin(lookup))->second[0]];
            }
        }
        return "";
    }
};

kamyu-c-once-twice-10v81pq:
// Time:  O(n)
// Space: O(1)

// dp, bitmasks
class Solution {
public:
    vector<int> onceTwice(vector<int>& nums) {
        vector<int> dp(3), new_dp(3);
        dp[0] = ~0;
        for (const auto& x : nums) {
            for (int i = 0; i < 3; ++i) {
                new_dp[i] = (x & dp[i - 1 >= 0 ? i - 1 : 2]) | (~x & dp[i]);
            }
            swap(dp, new_dp);
        }
        vector<int> dp2(3), new_dp2(3);
        dp2[0] = ~0;
        for (const auto& x : nums) {
            if ((~x & dp[1]) || (x & dp[2])) {
                continue;
            }
            for (int i = 0; i < 3; ++i) {
                new_dp2[i] = (x & dp2[i - 1 >= 0 ? i - 1 : 2]) | (~x & dp2[i]);
            }
            swap(dp2, new_dp2);
        }
        return {dp2[1], (dp2[1] ^ dp[1]) | dp[2]};
    }
};

kamyu-c-one-edit-distance-0huywvp:
// Time:  O(m + n)
// Space: O(1)

class Solution {
public:
    bool isOneEditDistance(string s, string t) {
        const int m = s.length(), n = t.length();
        if (m > n) {
            return isOneEditDistance(t, s);
        }
        if (n - m > 1) {
            return false;
        }

        int i = 0, shift = n - m;
        while (i < m && s[i] == t[i]) {
            ++i;
        }
        if (shift == 0) {
            ++i;
        }
        while (i < m && s[i] == t[i + shift]) {
            ++i;
        }

        return i == m;
    }
};

kamyu-c-ones-and-zeroes-0nud7h6:
// Time:  O(s * m * n), s is the size of the array.
// Space: O(m * n)

class Solution {
public:
    int findMaxForm(vector<string>& strs, int m, int n) {
        vector<vector<int>> dp(m + 1, vector<int>(n + 1));
        for (const auto &str : strs) {
            int zero_count = 0, one_count = 0;
            for (const auto& c : str) {
                if (c == '0') {
                    ++zero_count;
                } else if (c == '1') {
                    ++one_count;
                }
            }

            for (int i = m; i - zero_count >= 0; --i) {
            	for (int j = n; j - one_count >= 0; --j) {
                    dp[i][j] = max(dp[i][j], dp[i - zero_count][j - one_count] + 1);
            	}
            }
        }
        return dp[m][n];
    }
};

