// Time:  O(k * n^k + d), n is the number of alphabets,
//                        k is the length of target,
//                        d is the size of deadends
// Space: O(k * n^k + d)

class Solution {
public:
    int openLock(vector<string>& deadends, string target) {
        unordered_set<string> dead(deadends.begin(), deadends.end());
        vector<string> q{"0000"};
        unordered_set<string> lookup{"0000"};
        int depth = 0;
        while (!q.empty()) {
            vector<string> next_q;
            for (const auto& node : q) {
                if (node == target) {
                    return depth;
                }
                if (dead.count(node)) {
                    continue;
                }
                for (int i = 0; i < 4; ++i) {
                    auto n = node[i] - '0';
                    for (const auto& d : {-1, 1}) {
                        auto nn = (n + d + 10) % 10;
                        auto neighbor = node;
                        neighbor[i] = '0' + nn;
                        if (!lookup.count(neighbor)) {
                            lookup.emplace(neighbor);
                            next_q.emplace_back(neighbor);
                        }
                    }
                }
            }
            swap(q, next_q);
            ++depth;
        }
        return -1;
    }
};

kamyu-c-operations-on-tree-1imwd0t:
// Time:  ctor:    O(n)
//        lock:    O(1)
//        unlock:  O(1)
//        upgrade: O(n)
// Space: O(n)

class LockingTree {
public:
    LockingTree(vector<int>& parent)
      : parent_(parent)
      , children_(size(parent)) {
        for (int i = 0; i < size(parent); ++i) {
            if (parent[i] != -1) {
                children_[parent_[i]].emplace_back(i);
            }
        }
    }

    bool lock(int num, int user) {
        if (locked_.count(num)) {
            return false;
        }
        locked_[num] = user;
        return true;
    }

    bool unlock(int num, int user) {
        if (!locked_.count(num) || locked_[num] != user) {
            return false;
        }
        locked_.erase(num);
        return true;
    }

    bool upgrade(int num, int user) {
        for (int node = num; node != -1; node = parent_[node]) {
            if (locked_.count(node)) {
                return false;
            }
        }
        bool result = false;
        vector<int> stk = {num};
        while (!empty(stk)) {
            auto node = stk.back(); stk.pop_back();
            for (const auto& child : children_[node]) {
                if (locked_.count(child)) {
                    locked_.erase(child);
                    result = true;
                }
                stk.emplace_back(child);
            }
        }
        if (result) {
            locked_[num] = user;
        }
        return result;
    }

private:
    const vector<int>& parent_;
    vector<vector<int>> children_;
    unordered_map<int, int> locked_;
};

