                            const int smallest = *min_element(tmp.cbegin(), tmp.cend());
                            const int i = distance(tmp.begin(), find(tmp.cbegin(), tmp.cend(), smallest));
                            vector<int> tmp2(tmp);
                            tmp2.erase(tmp2.begin() + i);
                            const int second_smallest = *min_element(tmp2.cbegin(), tmp2.cend());
