            min_cost[i % 2][2] = costs[i][2] +
                                 min(min_cost[(i - 1) % 2][0], min_cost[(i - 1) % 2][1]);
        }

        return min(min_cost[(n - 1) % 2][0],
                   min(min_cost[(n - 1) % 2][1], min_cost[(n - 1) % 2][2]));
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
