                vector<string> &path, vector<vector<string> > &ans) {
            if(start == s.size()) {
                ans.push_back(path);
                return;        
            }
            for(size_t i = start; i < s.size(); ++i) {
                if(p[start][i]) {
                    path.push_back(s.substr(start, i - start + 1));
                    dfs(s, p, i + 1, path, ans);
                    path.pop_back();
                }
            }
        }
};

