                stk.emplace_back(move(tokens), lookup);
                tokens = {""};
            } else if (c == ' ') {
                tokens.emplace_back();
            } else if (c == ')') {
                const auto& val = evaluate(tokens, &lookup);
                tie(tokens, lookup) = move(stk.back());
                stk.pop_back();
                tokens.back() += val;
            } else {
                tokens.back().push_back(c);
            }
        }
        return stoi(tokens[0]);
    }

private:
    string evaluate(const vector<string>& tokens, unordered_map<string, string>* lookup) {
        static const unordered_set<string> operators{"add", "mult"};
        if (operators.count(tokens[0])) {
            const auto& a = stoi(getval(*lookup, tokens[1]));
            const auto& b = stoi(getval(*lookup, tokens[2]));
            return to_string(tokens[0] == "add" ? a + b : a * b);
        } 
        for (int i = 1; i < tokens.size() - 1; i += 2) {
            if (!tokens[i + 1].empty()) {
                (*lookup)[tokens[i]] = getval(*lookup, tokens[i + 1]);
            }
        }
        return getval(*lookup, tokens.back());
    }

    string getval(const unordered_map<string, string>& lookup, const string& x) {
        return lookup.count(x) ? lookup.at(x) : x;
    }
};

kamyu-c-parsing-a-boolean-expression-1ee:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    bool parseBoolExpr(string expression) {
        int i = 0;
        return parse(expression, &i);
    }

private:
    bool parse(const string& expression, int *i) {
        static const string ops = "&|!";
        if (ops.find(expression[*i]) == string::npos) {
            bool result = expression[*i] == 't';
            ++(*i);
            return result;
        }
        const auto& op = expression[*i];
        *i += 2;
        vector<bool> stk;
        while (expression[*i] != ')') {
            if (expression[*i] == ',') {
                ++(*i);
                continue;
            }
            stk.emplace_back(parse(expression, i));
        }
        ++(*i);
        if (op == '&') {
            return all_of(stk.cbegin(), stk.cend(),
                          [](bool val) { return val; });
        }
        if (op == '|') {
            return any_of(stk.cbegin(), stk.cend(),
                          [](bool val) { return val; });
        }
        return !stk[0];
    }
};

