    vector<bool> pathExistenceQueries(int n, vector<int>& nums, int maxDiff, vector<vector<int>>& queries) {
        vector<int> prefix(n);
        for (int i = 0; i < n - 1; ++i) {
            prefix[i + 1] = prefix[i] + (nums[i + 1] - nums[i] <= maxDiff ? 0 : 1);
        }
        vector<bool> result(size(queries));
