    bool possibleBipartition(int N, vector<vector<int>>& dislikes) {
        vector<vector<int>> adj(N);
        for (const auto& dislike : dislikes) {
            int u = dislike[0] - 1, v = dislike[1] - 1;
            adj[u].emplace_back(v);
            adj[v].emplace_back(u);
        }

        vector<int> color(N);
        color[0] = 1;
        queue<int> q({0});
