// simulation, deque
class Solution {
public:
    string processStr(string s) {
        deque<char> dq;
        bool right = true;
        for (const auto& x : s) {
            if (x == '*') {
                if (empty(dq)) {
                    continue;
                }
                if (right) {
                    dq.pop_back();
                } else {
                    dq.pop_front();
                }
            } else if (x == '#') {
                const int l = size(dq);
                for (int i = 0; i < l; ++i) {
                    dq.emplace_back(dq[i]);
                }
            } else if (x == '%') {
                right = !right;
            } else {
                if (right) {
                    dq.emplace_back(x);
                } else {
                    dq.emplace_front(x);
                }
            }
        }
        if (!right) {
            reverse(begin(dq), end(dq));
        }
        return string(cbegin(dq), cend(dq));
    }
};

// Time:  O(n)
// Space: O(1)

// backward simulation
class Solution {
public:
    char processStr(string s, long long k) {
        int64_t l = 0;
        for (const auto& x : s) {
            if (x == '*') {
                l = max(l - 1, static_cast<int64_t>(0));
            } else if (x == '#') {
                l <<= 1;
            } else if (x == '%') {
                continue;
            } else {
                ++l;
            }
        }
        if (k >= l) {
            return '.';
        }
        for (int i = size(s) - 1; i >= 0; --i) {
            const auto& x = s[i];
            if (x == '*') {
                ++l;
            } else if (x == '#') {
                l >>= 1;
                if (k >= l) {
                    k -= l;
                }
            } else if (x == '%') {
                k = (l - 1) - k;
            } else {
                if (--l == k) {
                    return x;
                }
            }
        }
        return 'x';
    }
};

kamyu-c-process-tasks-using-servers-00ds:
// Time:  O(n + mlogn)
// Space: O(n)

class Solution {
public:
    vector<int> assignTasks(vector<int>& servers, vector<int>& tasks) {
        vector<pair<int, int>> idle;
        for (int i = 0; i < size(servers); ++i) {
            idle.emplace_back(servers[i], i);
        }
        make_heap(begin(idle), end(idle), greater<>());
        vector<tuple<int, int, int>> working;

        vector<int> result;
        for (int i = 0, t = 0; i < size(tasks); ++i) {
            t = !empty(idle) ? max(t, i) : get<0>(working.front());
            while (!empty(working) && get<0>(working.front()) <= t) {
                const auto [_, w, idx] = working.front(); pop_heap(begin(working), end(working), greater<>()); working.pop_back();
                idle.emplace_back(w, idx); push_heap(begin(idle), end(idle), greater<>());
            }
            const auto [w, idx] = idle.front(); pop_heap(begin(idle), end(idle), greater<>()); idle.pop_back();
            working.emplace_back(t + tasks[i], w, idx); push_heap(begin(working), end(working), greater<>());
            result.emplace_back(idx);
        }
        return result;
    }
};

