        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& u : q) {
                ++result;
                for (const auto& v : adj[u]) {
                    if (lookup[v]) {
                        continue;
                    }
                    lookup[v] = true;
                    new_q.emplace_back(v);
                }
            }
            q = move(new_q);
        }
        return result;
    }
};

