kamyu-c-reformat-phone-number-0xqr3jf:
// Time:  O(n)
// Space: O(1)

// inplace solution
class Solution {
public:
    string reformatNumber(string number) {
        int src_len = 0;
        for (const auto& c : number) {  // remove non-digit characters
            if (isdigit(c)) {
                number[src_len++] = c;
            }
        }
        int dst_len = src_len + (src_len - 1) / 3;
        number.resize(dst_len);  // resize the buffer to expected final size
        for (int i = src_len - 1, curr = dst_len - 1, l = (3 - src_len % 3) % 3; i >= 0; --i, ++l) {
            if (l && l % 3 == 0) {  // group by 3 digits
                number[curr--] = '-';
            }
            number[curr--] = number[i];
        }
        if (dst_len >= 3 && number[dst_len - 2] == '-') {  // adjust for the 4 digits case
            swap(number[dst_len - 3], number[dst_len - 2]);
        }
        return number;
    }
};

kamyu-c-reformat-the-string-1y8on52:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    string reformat(string s) {
        unordered_map<char, int> count;
        int alpha_cnt = 0;
        for (const auto& c : s) {
            ++count[c];
            if (isalpha(c)) {
                ++alpha_cnt;
            }
        }
        if (abs(int(s.length()) - 2 * alpha_cnt) > 1) {
            return "";
        }

        char a = 'a', a_end = 'z';
        char b = '0', b_end = '9';
        if (alpha_cnt < s.length() - alpha_cnt) {
            swap(a, b);
            swap(a_end, b_end);
        }
        string result;
        while (result.length() < s.length()) {
            result.push_back(a = next_char(a, a_end, &count));
            result.push_back(b = next_char(b, b_end, &count));
        }
        if (result.back() == '\0') {
            result.pop_back();
        }
        return result;
    }

private:
    char next_char(char start, char end, unordered_map<char, int> *count) {
        for (char c = start; c <= end; ++c) {
            if ((*count)[c]) {
                --(*count)[c];
                return c;
            }
        }
        return '\0';
    }
};

kamyu-c-regions-cut-by-slashes-1m3jsw0:
// Time:  O(n^2)
// Space: O(n^2)

class Solution {
public:
    int regionsBySlashes(vector<string>& grid) {
        UnionFind union_find(grid.size() * grid.size() * 4);
        for (int i = 0; i < grid.size(); ++i) {
            for (int j = 0; j < grid[0].size(); ++j) {
                if (i) {
                    union_find.union_set(index(grid.size(), i - 1, j, S),
                                         index(grid.size(), i, j, N));
                }
                if (j) {
                    union_find.union_set(index(grid.size(), i, j - 1, E),
                                         index(grid.size(), i, j, W));
                }
                if (grid[i][j] != '/') {
                    union_find.union_set(index(grid.size(), i, j, N),
                                         index(grid.size(), i, j, E));
                    union_find.union_set(index(grid.size(), i, j, S),
                                         index(grid.size(), i, j, W));
                }
                if (grid[i][j] != '\\') {
                    union_find.union_set(index(grid.size(), i, j, W),
                                         index(grid.size(), i, j, N));
                    union_find.union_set(index(grid.size(), i, j, E),
                                         index(grid.size(), i, j, S));
                }
            }
        }
        return union_find.size();
    }

private:
    enum NODES {N, E, S, W};

    class UnionFind {
        public:
            UnionFind(const int n) : set_(n), count_(n) {
                iota(set_.begin(), set_.end(), 0);
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            void union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root != y_root) {
                    set_[min(x_root, y_root)] = max(x_root, y_root);
                    --count_;
                }
            }

            int size() const {
                return count_;
            }

        private:
            vector<int> set_;
            int count_;
    };

    int index(int n, int i, int j, int k) {
        return (i * n + j) * 4 + k;
    }
};

