kamyu-c-remove-all-occurrences-of-a-subs:
// Time:  O(n + m)
// Space: O(n + m)

// kmp solution
class Solution {
public:
    string removeOccurrences(string s, string part) {
        const auto& prefix = getPrefix(part);
        string result;
        vector<int> lookup;
        int i = -1;
        for (const auto& c : s) {
            while (i != -1 && part[i + 1] != c) {
                i = prefix[i];
            }
            if (part[i + 1] == c) {
                ++i;
            }
            result.push_back(c);
            lookup.emplace_back(i);
            if (i == size(part) - 1) {
                result.resize(size(result) - size(part));
                lookup.resize(size(lookup) - size(part));
                i = !empty(lookup) ? lookup.back() : -1;
            }
        }
        return result;
    }

private:
    vector<int> getPrefix(const string& pattern) {
        vector<int> prefix(size(pattern), -1);
        int j = -1;
        for (int i = 1; i < size(pattern); ++i) {
            while (j != -1 && pattern[j + 1] != pattern[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == pattern[i]) {
                ++j;
            }
            prefix[i] = j;
        }
        return prefix;
    }
};

kamyu-c-remove-all-ones-with-row-and-col:
// Time:  O(m * n * 2^(m * n))
// Space: O(2^(m * n))

// dp, bitmasks
class Solution {
public:
    int removeOnes(vector<vector<int>>& grid) {
        static const int INF = numeric_limits<int>::max();

        vector<int> rows(size(grid));
        int mask = 0, bit = 1;
        for (int j = 0; j < size(grid[0]); ++j) {
            mask += bit;
            bit <<= 1;
        }
        for (int i = 0; i < size(grid); ++i) {
            rows[i] = mask;
            mask <<= size(grid[0]);
        }

        vector<int> cols(size(grid[0]));
        mask = 0, bit = 1;
        for (int i = 0; i < size(grid); ++i) {
            mask += bit;
            bit <<= size(grid[0]);
        }
        for (int j = 0; j < size(grid[0]); ++j) {
            cols[j] = mask;
            mask <<= 1;
        }

        int full_mask = (1 << (size(grid) * size(grid[0]))) - 1;
        vector<vector<int>> masks(size(grid), vector<int>(size(grid[0]), full_mask));
        int target = 0;
        bit = 1;
        for (int i = 0; i < size(grid); ++i) {
            for (int j = 0; j < size(grid[0]); ++j) {
                target += bit * grid[i][j];
                masks[i][j] -= (rows[i] + cols[j] - bit);
                bit <<= 1;
            }
        }

        vector<int> dp(target + 1, INF);
        dp[0] = 0;
        for (int mask = 1; mask <= target; ++mask) {
            for (int i = 0; i < size(grid); ++i) {
                for (int j = 0; j < size(grid[0]); ++j) {
                    if (grid[i][j] && dp[mask & masks[i][j]] != INF) {
                        dp[mask] = min(dp[mask], dp[mask & masks[i][j]] + 1);
                    }
                }
            }
        }
        return dp[target];
    }
};

// Time:  O(m * n)
// Space: O(1)

