kamyu-c-remove-k-balanced-substrings-022:
// Time:  O(n)
// Space: O(n)

// stack
class Solution {
public:
    string removeSubstring(string s, int k) {
        int cnt = 0;
        const auto& count = [&](char x) {
            if (x == '(') {
                if (cnt < k) {
                    ++cnt;
                } else if (cnt > k) {
                    cnt = 1;
                }
            } else {
                if (cnt >= k) {
                    ++cnt;
                } else {
                    cnt = 0;
                }
            }
        };

        string result;
        for (const auto& x : s) {
            result.push_back(x);
            count(x);
            if (cnt != 2 * k) {
                continue;
            }
            for (int _ = 0; _ < 2 * k; ++_) {
                result.pop_back();
            }
            cnt = 0;
            for (int i = max(static_cast<int>(size(result)) - (2 * k - 1), 0); i < size(result); ++i) {
                count(result[i]);
            }
        }
        return result;
    }
};

kamyu-c-remove-k-digits-1xhznyh:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    string removeKdigits(string num, int k) {
        // If a digit is greater than next one, delete it.
        string s;
        for (const auto c : num) {
            while (k > 0 && !s.empty() && s.back() > c) {
                s.pop_back();
                --k;
            }
            s.push_back(c);
        }

        // If all digits are increasingly sorted, delete last.
        s.resize(s.length() - k);

        // Strip all leading '0'
        return s.empty() || s == "0" ? "0" : s.substr(s.find_first_not_of('0'));
    }
};

kamyu-c-remove-letter-to-equalize-freque:
// Time:  O(n)
// Space: O(1)

// freq table, edge cases
class Solution {
public:
    bool equalFrequency(string word) {
        vector<int> cnt(26);
        for (const auto& c : word) {
            ++cnt[c - 'a'];
        }
        unordered_map<int, int> cnt2;
        for (const auto& c : cnt) {
            if (c) {
                ++cnt2[c];
            }
        }
        if (size(cnt2) > 2) {
            return false;
        }
        if (size(cnt2) == 1) {
            return cbegin(cnt2)->first == 1 || cbegin(cnt2)->second == 1;
        }
        int a = cbegin(cnt2)->first;
        int b = next(cbegin(cnt2))->first;
        if (a > b) {
            swap(a, b);
        }
        return (a == 1 && cnt2[a] == 1) || (a + 1 == b && cnt2[b] == 1);
    }
};

// Time:  O(26 * n)
// Space: O(1)
// brute force, freq table
class Solution2 {
public:
    bool equalFrequency(string word) {
        vector<int> cnt(26);
        for (const auto& c : word) {
            ++cnt[c - 'a'];
        }
        for (const auto& c : word) {
            --cnt[c - 'a'];
            int i = 0;
            for (int prev = 0; i < size(cnt); ++i) {
                if (!cnt[i]) {
                    continue;
                }
                if (prev && prev != cnt[i]) {
                    break;
                }
                prev = cnt[i];
            }
            if (i == size(cnt)) {
                return true;
            }
            ++cnt[c - 'a'];
        }
        return false;
    }
};

