// Space: O(1)
class Solution2 {
public:
    ListNode* removeElements(ListNode* head, int val) {
        for (auto *indirect = &head; *indirect != nullptr; ) {
            if ((*indirect)->val == val) {
                *indirect = (*indirect)->next;
                continue;
            }
            indirect = &((*indirect)->next) ; 
        }
        return head;
    }
};

kamyu-c-remove-max-number-of-edges-to-ke:
// Time:  O(n + m * α(n)) ~= O(n + m)
// Space: O(n)

class Solution {
public:
    int maxNumEdgesToRemove(int n, vector<vector<int>>& edges) {
        int result = 0;
        UnionFind union_find_a(n), union_find_b(n);
        for (const auto& edge : edges) {
            int t = edge[0], i = edge[1], j = edge[2];
            if (t != 3) {
                continue;
            }
            bool a = union_find_a.union_set(i - 1, j - 1);
            bool b = union_find_b.union_set(i - 1, j - 1);
            if (!a && !b) {
                ++result;
            }
        }
        for (const auto& edge : edges) {
            int t = edge[0], i = edge[1], j = edge[2];
            if (t == 1) {
                if (!union_find_a.union_set(i - 1, j - 1)) {
                    ++result;
                }
            } else if (t == 2) {
                if (!union_find_b.union_set(i - 1, j - 1)) {
                    ++result;
                }
            }
        }
        return union_find_a.size() == 1 && union_find_b.size() == 1 ? result : -1;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), size_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            set_[max(x_root, y_root)] = min(x_root, y_root);
            --size_;
            return true;
        }

        int size() const {
            return size_;
        }

    private:
        vector<int> set_;
        int size_;
    };
};

kamyu-c-remove-methods-from-project-1q4p:
// Time:  O(n + e)
// Space: O(n + e)

// bfs
class Solution {
public:
    vector<int> remainingMethods(int n, int k, vector<vector<int>>& invocations) {
        vector<vector<int>> adj(n);
        const auto& bfs = [&]() {
            vector<bool> lookup(n);
            lookup[k] = true;
            vector<int> q = {k};
            while (!empty(q)) {
                vector<int> new_q;
                for (const auto& u : q) {
                    for (const auto& v : adj[u]) {
                        if (lookup[v]) {
                            continue;
                        }
                        lookup[v] = true;
                        new_q.emplace_back(v);
                    }
                }
                q = move(new_q);
            }
            return lookup;
        };

        for (const auto& e : invocations) {
            adj[e[0]].emplace_back(e[1]);
        }
        const auto& lookup = bfs();
        for (const auto& e : invocations) {
            if (lookup[e[0]] != lookup[e[1]]) {
                vector<int> result(n);
                iota(begin(result), end(result), 0);
                return result;
            }
        }
        vector<int> result;
        for (int u = 0; u < n; ++u) {
            if (!lookup[u]) {
                result.emplace_back(u);
            }
        }
        return result;
    }
};

